package neueda.in.TransactionMonitoring.entity;

public enum RuleType {
	AMOUNT_THRESHOLD,
	VELOCITY,
	NEW_PAYEE,
	DAILY_LIMIT
}

import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { CheckCircle2, AlertCircle, ArrowLeft, Send, Plus, CreditCard } from 'lucide-react';
import { useAuthStore } from '@/features/auth/store/authStore';
import { createTransaction } from '@/lib/api/transactions';
import { getRules } from '@/lib/api/rules';
import { mockPayees } from '@/mocks/data';
import { formatCurrency } from '@/lib/utils';
import { toast } from '@/components/common/Toast';

const schema = z.object({
  payeeId:            z.string().min(1, 'Please select a payee'),
  payeeAccountNumber: z.string().min(4, 'Payee account number must be at least 4 digits'),
  amount:             z.coerce.number().positive('Amount must be greater than 0'),
  description:        z.string().max(255).optional(),
});

type FormValues = z.infer<typeof schema>;
type Step = 'form' | 'review' | 'success';

export default function SendMoneyPage() {
  const { user }      = useAuthStore();
  const navigate      = useNavigate();
  const queryClient   = useQueryClient();
  const [step, setStep] = useState<Step>('form');
  const [formData, setFormData] = useState<FormValues | null>(null);
  const [txRef, setTxRef]       = useState<string>('');

  // ── Known Payee Accounts Tracking (To prevent duplicate New Payee alert on 2nd transfer) ─
  const [knownPayees, setKnownPayees] = useState<Set<string>>(() => {
    const saved = localStorage.getItem('hawkeye_known_payees');
    if (saved) {
      try {
        return new Set(JSON.parse(saved));
      } catch (e) {}
    }
    // Initial known seed payees
    return new Set(['ACC-908123', 'ACC-001', 'PAY-001', 'PAY-002', 'PAY-003', 'PAY-004', 'PAY-005', 'Amazon Marketplace', 'Starbucks Coffee']);
  });

  // ── Source Accounts Management for Single User ─────────────────────────────
  const [userAccounts, setUserAccounts] = useState<string[]>([
    user?.accountId || 'ACC-001',
    'ACC-002 (Savings)',
    'ACC-003 (Corporate)',
  ]);
  const [selectedSourceAccount, setSelectedSourceAccount] = useState<string>(user?.accountId || 'ACC-001');
  const [isAddingNewAccount, setIsAddingNewAccount] = useState(false);
  const [newAccountInput, setNewAccountInput] = useState('');

  const handleAddNewSourceAccount = () => {
    if (!newAccountInput.trim()) return;
    const formatted = newAccountInput.trim().toUpperCase();
    if (!userAccounts.includes(formatted)) {
      setUserAccounts((prev) => [...prev, formatted]);
    }
    setSelectedSourceAccount(formatted);
    setIsAddingNewAccount(false);
    setNewAccountInput('');
    toast.success(`Account ${formatted} added to your account list!`);
  };

  const { register, handleSubmit, watch, formState: { errors } } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: { payeeAccountNumber: 'ACC-908123' },
  });

  // Query active rules from backend DB
  const { data: rulesPage } = useQuery({
    queryKey: ['rules', 'active-evaluate'],
    queryFn: () => getRules({ status: 'ACTIVE', size: 100 }),
  });
  const activeRules = rulesPage?.content || [];

  const selectedPayee = mockPayees.find((p) => p.payeeId === watch('payeeId'));

  const [alertPopup, setAlertPopup] = useState<{ ruleName: string; severity: string; message: string } | null>(null);
  const [emailPopup, setEmailPopup] = useState<{ recipient: string; subject: string } | null>(null);

  const mutation = useMutation({
    mutationFn: createTransaction,
    onSuccess: (data) => {
      setTxRef(`TXN-${data.transactionId}`);
      setStep('success');

      // Immediately invalidate and refetch transactions so it displays at top of Transactions page
      void queryClient.invalidateQueries({ queryKey: ['transactions'] });
      void queryClient.invalidateQueries({ queryKey: ['alerts'] });

      // ── Evaluate ONLY against ACTIVE rules in Backend DB ───────────────────
      const amountRule = activeRules.find((r) => r.ruleType === 'AMOUNT_THRESHOLD');
      const dailyRule = activeRules.find((r) => r.ruleType === 'DAILY_LIMIT');
      const newPayeeRule = activeRules.find((r) => r.ruleType === 'NEW_PAYEE');

      let triggeredAlert = null;

      const payeeKey = formData?.payeeAccountNumber?.trim() || formData?.payeeId || selectedPayee?.payeeName || '';
      const isNewPayee = payeeKey ? !knownPayees.has(payeeKey) : false;

      if (amountRule && formData && formData.amount >= (amountRule.parameters?.thresholdAmount || 1000)) {
        triggeredAlert = {
          ruleName: amountRule.ruleName || 'Amount Threshold Rule',
          severity: amountRule.severity || 'HIGH',
          message: `Transaction amount $${formData.amount} exceeded $${amountRule.parameters?.thresholdAmount || 1000} active limit!`,
        };
      } else if (dailyRule && formData && formData.amount >= (dailyRule.parameters?.dailyLimitAmount || 2000)) {
        triggeredAlert = {
          ruleName: dailyRule.ruleName || 'Daily Limit Rule',
          severity: dailyRule.severity || 'CRITICAL',
          message: `Transaction amount $${formData.amount} exceeded daily limit threshold!`,
        };
      } else if (newPayeeRule && isNewPayee) {
        // Trigger New Payee Alert ONLY on 1st transfer to a new vendor
        triggeredAlert = {
          ruleName: newPayeeRule.ruleName || 'New Payee Detection Rule',
          severity: newPayeeRule.severity || 'MEDIUM',
          message: `First-time transfer to new payee account ${formData?.payeeAccountNumber} (${selectedPayee?.payeeName || formData?.payeeId})`,
        };

        // Add payee to knownPayees so 2nd transfer does NOT trigger New Payee Alert again
        setKnownPayees((prev) => {
          const updated = new Set(prev);
          updated.add(payeeKey);
          localStorage.setItem('hawkeye_known_payees', JSON.stringify(Array.from(updated)));
          return updated;
        });
      }

      setAlertPopup(triggeredAlert);

      // Trigger Email Sent Notification Popup
      setEmailPopup({
        recipient: user?.email || 'customer@hawkeye.com',
        subject: `Transaction Alert Notification — ${triggeredAlert ? triggeredAlert.ruleName : 'DEBIT Confirmation'}`,
      });

      toast.success('DEBIT Transaction submitted successfully!');
    },
    onError: (err) => {
      toast.error('Transaction failed', err instanceof Error ? err.message : 'Unknown error');
      setStep('form');
    },
  });

  const onReview = (values: FormValues) => {
    setFormData(values);
    setStep('review');
  };

  const onConfirm = () => {
    if (!formData) return;
    mutation.mutate({
      accountId:          selectedSourceAccount.split(' ')[0],
      payeeId:            formData.payeeAccountNumber || formData.payeeId,
      payeeName:          selectedPayee?.payeeName || 'Vendor Payee',
      payeeType:          selectedPayee?.payeeType || 'Personal',
      amount:             formData.amount,
      transactionType:    'DEBIT', // Strictly DEBIT
      description:        formData.description,
      timestamp:          new Date().toISOString(),
    });
  };

  // ── Success screen ─────────────────────────────────────────────────────────
  if (step === 'success') {
    return (
      <div className="flex min-h-[60vh] items-center justify-center animate-fade-in">
        <div className="max-w-md w-full text-center">
          <div className="mx-auto mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-green-100 dark:bg-green-900/30">
            <CheckCircle2 className="h-10 w-10 text-green-600 dark:text-green-400" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">DEBIT Transaction Submitted!</h2>
          <p className="mt-2 text-gray-500 dark:text-gray-400">
            Your transfer has been processed and recorded in Transaction Service.
          </p>
          <div className="mt-4 rounded-xl border border-gray-200 bg-gray-50 px-6 py-4 dark:border-gray-700 dark:bg-gray-800">
            <p className="text-xs text-gray-400">Reference ID</p>
            <p className="mt-1 font-mono text-lg font-bold text-hawk-700 dark:text-hawk-300">{txRef}</p>
          </div>

          {/* Rule Alert Generated Popup Banner */}
          {alertPopup && (
            <div className={`mt-4 rounded-xl border p-4 text-left shadow-md ${
              alertPopup.severity === 'HIGH' || alertPopup.severity === 'CRITICAL'
                ? 'border-red-300 bg-red-50 text-red-900 dark:border-red-800 dark:bg-red-950/40 dark:text-red-200'
                : alertPopup.severity === 'MEDIUM'
                ? 'border-amber-300 bg-amber-50 text-amber-900 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-200'
                : 'border-blue-300 bg-blue-50 text-blue-900 dark:border-blue-800 dark:bg-blue-950/40 dark:text-blue-200'
            }`}>
              <div className="flex items-start gap-3">
                <span className="text-xl">
                  {alertPopup.severity === 'HIGH' || alertPopup.severity === 'CRITICAL' ? '' : '⚠️'}
                </span>
                <div className="flex-1 text-xs">
                  <div className="flex items-center justify-between">
                    <strong className="font-bold text-sm">SECURITY ALERT GENERATED</strong>
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${
                      alertPopup.severity === 'HIGH' ? 'bg-red-600 text-white' : 'bg-amber-500 text-white'
                    }`}>
                      {alertPopup.severity} SEVERITY
                    </span>
                  </div>
                  <p className="mt-1 font-semibold">{alertPopup.ruleName}</p>
                  <p className="mt-0.5 opacity-90">{alertPopup.message}</p>
                </div>
              </div>
            </div>
          )}

          {/* Email Notification Dispatched Popup Banner */}
          {emailPopup && (
            <div className="mt-3 rounded-xl border border-indigo-200 bg-indigo-50/80 p-3.5 text-left text-xs text-indigo-900 dark:border-indigo-800 dark:bg-indigo-950/40 dark:text-indigo-200">
              <div className="flex items-center gap-2.5">
                <span className="text-base"></span>
                <div className="flex-1">
                  <strong className="font-bold text-xs block text-indigo-950 dark:text-indigo-100">Email Notification Dispatched</strong>
                  <p className="text-[11px] text-indigo-700 dark:text-indigo-300">
                    Confirmation & alert email sent to <strong>{emailPopup.recipient}</strong>
                  </p>
                </div>
              </div>
            </div>
          )}

          <div className="mt-6 flex gap-3 justify-center">
            <button
              onClick={() => { setStep('form'); setFormData(null); setAlertPopup(null); setEmailPopup(null); }}
              className="rounded-lg border border-gray-300 px-5 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300"
            >
              Send Another
            </button>
            <button
              onClick={() => navigate('/admin/metrics')}
              className="rounded-lg bg-hawk-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-hawk-700"
            >
              View Transactions
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── Review modal overlay ───────────────────────────────────────────────────
  if (step === 'review' && formData) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
        <div className="w-full max-w-md animate-fade-in rounded-2xl bg-white p-6 shadow-2xl dark:bg-gray-900">
          <h3 className="mb-4 text-lg font-semibold text-gray-900 dark:text-white">Review DEBIT Transaction</h3>
          <dl className="space-y-3 text-sm">
            {[
              { label: 'From Account',         value: selectedSourceAccount },
              { label: 'Payee',                value: selectedPayee?.payeeName ?? formData.payeeId },
              { label: 'Payee Account No.',    value: <span className="font-mono text-xs">{formData.payeeAccountNumber}</span> },
              { label: 'Amount',               value: <span className="font-bold text-red-600">-{formatCurrency(formData.amount)}</span> },
              { label: 'Type',                 value: <span className="font-bold text-red-600">DEBIT</span> },
              { label: 'Note',                 value: formData.description || '—' },
            ].map(({ label, value }) => (
              <div key={label} className="flex justify-between gap-4">
                <dt className="text-gray-500 dark:text-gray-400">{label}</dt>
                <dd className="font-medium text-gray-900 text-right dark:text-white">{value}</dd>
              </div>
            ))}
          </dl>
          <div className="mt-4 rounded-lg bg-yellow-50 px-4 py-3 text-xs text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400 flex gap-2">
            <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
            Please confirm details above before submitting. DEBIT transfers are final.
          </div>
          <div className="mt-5 flex gap-3">
            <button
              onClick={() => setStep('form')}
              className="flex-1 rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300"
            >
              <ArrowLeft className="mr-1 inline h-4 w-4" /> Edit
            </button>
            <button
              onClick={onConfirm}
              disabled={mutation.isPending}
              className="flex-1 rounded-lg bg-hawk-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-hawk-700 disabled:opacity-60 flex items-center justify-center gap-2"
            >
              <Send className="h-4 w-4" />
              {mutation.isPending ? 'Processing…' : 'Confirm & Send'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── Main form ──────────────────────────────────────────────────────────────
  return (
    <div className="mx-auto max-w-lg animate-fade-in">
      <div className="mb-6 flex items-center gap-3">
        <button onClick={() => navigate(-1)} className="text-gray-400 hover:text-gray-600">
          <ArrowLeft className="h-5 w-5" />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Send Money</h1>
          <p className="text-xs text-gray-400">Perform DEBIT transaction to beneficiary account</p>
        </div>
      </div>

      <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-900">
        <form onSubmit={handleSubmit(onReview)} className="space-y-4">

          {/* Source Account Selector */}
          <div>
            <div className="flex items-center justify-between mb-1">
              <label className="text-xs font-semibold text-gray-700 dark:text-gray-300 flex items-center gap-1.5">
                <CreditCard className="h-3.5 w-3.5 text-blue-500" />
                From Account (Source Account)
              </label>
              {!isAddingNewAccount && (
                <button
                  type="button"
                  onClick={() => setIsAddingNewAccount(true)}
                  className="flex items-center gap-1 text-[11px] font-bold text-blue-600 hover:underline"
                >
                  <Plus className="h-3 w-3" /> Add New Account
                </button>
              )}
            </div>

            {isAddingNewAccount ? (
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newAccountInput}
                  onChange={(e) => setNewAccountInput(e.target.value)}
                  placeholder="e.g. ACC-004 / 987654321"
                  className="flex-1 rounded-xl border border-gray-300 px-3 py-2 text-xs font-mono outline-none focus:border-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                <button
                  type="button"
                  onClick={handleAddNewSourceAccount}
                  className="rounded-xl bg-blue-600 px-3 py-2 text-xs font-bold text-white hover:bg-blue-700"
                >
                  Add
                </button>
                <button
                  type="button"
                  onClick={() => setIsAddingNewAccount(false)}
                  className="rounded-xl border border-gray-200 px-3 py-2 text-xs text-gray-500 hover:bg-gray-50 dark:border-gray-700 dark:text-gray-300"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <select
                value={selectedSourceAccount}
                onChange={(e) => setSelectedSourceAccount(e.target.value)}
                className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs font-mono outline-none focus:border-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              >
                {userAccounts.map((acc) => (
                  <option key={acc} value={acc}>{acc}</option>
                ))}
              </select>
            )}
          </div>

          {/* Payee Selection */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">Select Payee / Merchant</label>
            <select
              {...register('payeeId')}
              className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
            >
              <option value="">Select payee…</option>
              {mockPayees.map((p) => (
                <option key={p.payeeId} value={p.payeeId}>{p.payeeName} ({p.payeeCategory})</option>
              ))}
            </select>
            {errors.payeeId && <p className="mt-1 text-xs text-red-600">{errors.payeeId.message}</p>}
          </div>

          {/* Payee Account Number */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">Payee Account Number</label>
            <input
              {...register('payeeAccountNumber')}
              type="text"
              placeholder="e.g. ACC-908123 / 9876543210"
              className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs font-mono outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
            />
            {errors.payeeAccountNumber && <p className="mt-1 text-xs text-red-600">{errors.payeeAccountNumber.message}</p>}
          </div>

          {/* Amount */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">Amount (USD)</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">$</span>
              <input
                {...register('amount')}
                type="number"
                step="any"
                placeholder="150.00"
                className="w-full rounded-xl border border-gray-300 py-2 pl-7 pr-3 text-xs outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              />
            </div>
            {errors.amount && <p className="mt-1 text-xs text-red-600">{errors.amount.message}</p>}
          </div>

          {/* Description */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">
              Note <span className="text-gray-400 font-normal">(optional)</span>
            </label>
            <input
              {...register('description')}
              type="text"
              placeholder="e.g. Vendor invoice payment"
              className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
            />
          </div>

          <button
            type="submit"
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-hawk-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-hawk-700 transition"
          >
            <Send className="h-4 w-4" />
            Review DEBIT Transaction
          </button>
        </form>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { CheckCircle2, AlertCircle, ArrowLeft, Send, Plus, CreditCard } from 'lucide-react';
import { useAuthStore } from '@/features/auth/store/authStore';
import { createTransaction, getTransactionAlerts } from '@/lib/api/transactions';
import { mockPayees } from '@/mocks/data';
import { formatCurrency } from '@/lib/utils';
import { toast } from '@/components/common/Toast';
import type { AlertSummary } from '@/lib/types';

const schema = z.object({
  payeeId:            z.string().min(1, 'Please select a payee'),
  payeeAccountNumber: z.string().min(4, 'Payee account number must be at least 4 digits'),
  amount:             z.coerce.number().positive('Amount must be greater than 0'),
  description:        z.string().max(255).optional(),
});

type FormValues = z.infer<typeof schema>;
type Step = 'form' | 'review' | 'success';

export default function SendMoneyPage() {
  const { user }      = useAuthStore();
  const navigate      = useNavigate();
  const queryClient   = useQueryClient();
  const [step, setStep] = useState<Step>('form');
  const [formData, setFormData] = useState<FormValues | null>(null);
  const [txRef, setTxRef]       = useState<string>('');

  // ── Source Accounts Management for Single User ─────────────────────────────
  const [userAccounts, setUserAccounts] = useState<string[]>([
    user?.accountId || 'ACC-001',
    'ACC-002 (Savings)',
    'ACC-003 (Corporate)',
  ]);
  const [selectedSourceAccount, setSelectedSourceAccount] = useState<string>(user?.accountId || 'ACC-001');
  const [isAddingNewAccount, setIsAddingNewAccount] = useState(false);
  const [newAccountInput, setNewAccountInput] = useState('');

  const handleAddNewSourceAccount = () => {
    if (!newAccountInput.trim()) return;
    const formatted = newAccountInput.trim().toUpperCase();
    if (!userAccounts.includes(formatted)) {
      setUserAccounts((prev) => [...prev, formatted]);
    }
    setSelectedSourceAccount(formatted);
    setIsAddingNewAccount(false);
    setNewAccountInput('');
    toast.success(`Account ${formatted} added to your account list!`);
  };

  const { register, handleSubmit, watch, formState: { errors } } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: { payeeAccountNumber: 'ACC-908123' },
  });

  const selectedPayee = mockPayees.find((p) => p.payeeId === watch('payeeId'));

  const [alertPopup, setAlertPopup] = useState<{ ruleName: string; severity: string; message: string } | null>(null);
  const [emailPopup, setEmailPopup] = useState<{ recipient: string; subject: string } | null>(null);

  const waitForPersistedAlerts = async (transactionId: number): Promise<AlertSummary[]> => {
    const maxAttempts = 10;
    const delayMs = 500;

    for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
      const alerts = await getTransactionAlerts(transactionId);
      if (alerts.length > 0) {
        return alerts;
      }
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }

    return [];
  };

  const mutation = useMutation({
    mutationFn: createTransaction,
    onSuccess: async (data) => {
      setTxRef(`TXN-${data.transactionId}`);
      setStep('success');

      // Refresh transaction datasets immediately.
      void queryClient.invalidateQueries({ queryKey: ['transactions'] });

      // Source-of-truth: read persisted alerts from backend for this transaction.
      const persistedAlerts = await waitForPersistedAlerts(data.transactionId);
      const latestAlert = persistedAlerts[0];

      setAlertPopup(
        latestAlert
          ? {
              ruleName: `Rule #${latestAlert.ruleId}`,
              severity: latestAlert.severity,
              message: latestAlert.alertMessage,
            }
          : null,
      );

      void queryClient.invalidateQueries({ queryKey: ['alerts'] });
      void queryClient.invalidateQueries({ queryKey: ['transaction'] });

      // Trigger Email Sent Notification Popup
      setEmailPopup({
        recipient: user?.email || 'customer@hawkeye.com',
        subject: `Transaction Alert Notification — ${latestAlert ? `Rule #${latestAlert.ruleId}` : 'DEBIT Confirmation'}`,
      });

      toast.success('DEBIT Transaction submitted successfully!');
    },
    onError: (err) => {
      toast.error('Transaction failed', err instanceof Error ? err.message : 'Unknown error');
      setStep('form');
    },
  });

  const onReview = (values: FormValues) => {
    setFormData(values);
    setStep('review');
  };

  const onConfirm = () => {
    if (!formData) return;
    mutation.mutate({
      accountId:          selectedSourceAccount.split(' ')[0],
      payeeId:            formData.payeeAccountNumber || formData.payeeId,
      payeeName:          selectedPayee?.payeeName || 'Vendor Payee',
      payeeType:          selectedPayee?.payeeType || 'Personal',
      amount:             formData.amount,
      transactionType:    'DEBIT', // Strictly DEBIT
      description:        formData.description,
      timestamp:          new Date().toISOString(),
    });
  };

  // ── Success screen ─────────────────────────────────────────────────────────
  if (step === 'success') {
    return (
      <div className="flex min-h-[60vh] items-center justify-center animate-fade-in">
        <div className="max-w-md w-full text-center">
          <div className="mx-auto mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-green-100 dark:bg-green-900/30">
            <CheckCircle2 className="h-10 w-10 text-green-600 dark:text-green-400" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">DEBIT Transaction Submitted!</h2>
          <p className="mt-2 text-gray-500 dark:text-gray-400">
            Your transfer has been processed and recorded in Transaction Service.
          </p>
          <div className="mt-4 rounded-xl border border-gray-200 bg-gray-50 px-6 py-4 dark:border-gray-700 dark:bg-gray-800">
            <p className="text-xs text-gray-400">Reference ID</p>
            <p className="mt-1 font-mono text-lg font-bold text-hawk-700 dark:text-hawk-300">{txRef}</p>
          </div>

          {/* Rule Alert Generated Popup Banner */}
          {alertPopup && (
            <div className={`mt-4 rounded-xl border p-4 text-left shadow-md ${
              alertPopup.severity === 'HIGH' || alertPopup.severity === 'CRITICAL'
                ? 'border-red-300 bg-red-50 text-red-900 dark:border-red-800 dark:bg-red-950/40 dark:text-red-200'
                : alertPopup.severity === 'MEDIUM'
                ? 'border-amber-300 bg-amber-50 text-amber-900 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-200'
                : 'border-blue-300 bg-blue-50 text-blue-900 dark:border-blue-800 dark:bg-blue-950/40 dark:text-blue-200'
            }`}>
              <div className="flex items-start gap-3">
                <span className="text-xl">
                  {alertPopup.severity === 'HIGH' || alertPopup.severity === 'CRITICAL' ? '' : '⚠️'}
                </span>
                <div className="flex-1 text-xs">
                  <div className="flex items-center justify-between">
                    <strong className="font-bold text-sm">SECURITY ALERT GENERATED</strong>
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${
                      alertPopup.severity === 'HIGH' ? 'bg-red-600 text-white' : 'bg-amber-500 text-white'
                    }`}>
                      {alertPopup.severity} SEVERITY
                    </span>
                  </div>
                  <p className="mt-1 font-semibold">{alertPopup.ruleName}</p>
                  <p className="mt-0.5 opacity-90">{alertPopup.message}</p>
                </div>
              </div>
            </div>
          )}

          {/* Email Notification Dispatched Popup Banner */}
          {emailPopup && (
            <div className="mt-3 rounded-xl border border-indigo-200 bg-indigo-50/80 p-3.5 text-left text-xs text-indigo-900 dark:border-indigo-800 dark:bg-indigo-950/40 dark:text-indigo-200">
              <div className="flex items-center gap-2.5">
                <span className="text-base"></span>
                <div className="flex-1">
                  <strong className="font-bold text-xs block text-indigo-950 dark:text-indigo-100">Email Notification Dispatched</strong>
                  <p className="text-[11px] text-indigo-700 dark:text-indigo-300">
                    Confirmation & alert email sent to <strong>{emailPopup.recipient}</strong>
                  </p>
                </div>
              </div>
            </div>
          )}

          <div className="mt-6 flex gap-3 justify-center">
            <button
              onClick={() => { setStep('form'); setFormData(null); setAlertPopup(null); setEmailPopup(null); }}
              className="rounded-lg border border-gray-300 px-5 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300"
            >
              Send Another
            </button>
            <button
              onClick={() => navigate('/admin/metrics')}
              className="rounded-lg bg-hawk-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-hawk-700"
            >
              View Transactions
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── Review modal overlay ───────────────────────────────────────────────────
  if (step === 'review' && formData) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
        <div className="w-full max-w-md animate-fade-in rounded-2xl bg-white p-6 shadow-2xl dark:bg-gray-900">
          <h3 className="mb-4 text-lg font-semibold text-gray-900 dark:text-white">Review DEBIT Transaction</h3>
          <dl className="space-y-3 text-sm">
            {[
              { label: 'From Account',         value: selectedSourceAccount },
              { label: 'Payee',                value: selectedPayee?.payeeName ?? formData.payeeId },
              { label: 'Payee Account No.',    value: <span className="font-mono text-xs">{formData.payeeAccountNumber}</span> },
              { label: 'Amount',               value: <span className="font-bold text-red-600">-{formatCurrency(formData.amount)}</span> },
              { label: 'Type',                 value: <span className="font-bold text-red-600">DEBIT</span> },
              { label: 'Note',                 value: formData.description || '—' },
            ].map(({ label, value }) => (
              <div key={label} className="flex justify-between gap-4">
                <dt className="text-gray-500 dark:text-gray-400">{label}</dt>
                <dd className="font-medium text-gray-900 text-right dark:text-white">{value}</dd>
              </div>
            ))}
          </dl>
          <div className="mt-4 rounded-lg bg-yellow-50 px-4 py-3 text-xs text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400 flex gap-2">
            <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
            Please confirm details above before submitting. DEBIT transfers are final.
          </div>
          <div className="mt-5 flex gap-3">
            <button
              onClick={() => setStep('form')}
              className="flex-1 rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300"
            >
              <ArrowLeft className="mr-1 inline h-4 w-4" /> Edit
            </button>
            <button
              onClick={onConfirm}
              disabled={mutation.isPending}
              className="flex-1 rounded-lg bg-hawk-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-hawk-700 disabled:opacity-60 flex items-center justify-center gap-2"
            >
              <Send className="h-4 w-4" />
              {mutation.isPending ? 'Processing…' : 'Confirm & Send'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── Main form ──────────────────────────────────────────────────────────────
  return (
    <div className="mx-auto max-w-lg animate-fade-in">
      <div className="mb-6 flex items-center gap-3">
        <button onClick={() => navigate(-1)} className="text-gray-400 hover:text-gray-600">
          <ArrowLeft className="h-5 w-5" />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Send Money</h1>
          <p className="text-xs text-gray-400">Perform DEBIT transaction to beneficiary account</p>
        </div>
      </div>

      <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-900">
        <form onSubmit={handleSubmit(onReview)} className="space-y-4">

          {/* Source Account Selector */}
          <div>
            <div className="flex items-center justify-between mb-1">
              <label className="text-xs font-semibold text-gray-700 dark:text-gray-300 flex items-center gap-1.5">
                <CreditCard className="h-3.5 w-3.5 text-blue-500" />
                From Account (Source Account)
              </label>
              {!isAddingNewAccount && (
                <button
                  type="button"
                  onClick={() => setIsAddingNewAccount(true)}
                  className="flex items-center gap-1 text-[11px] font-bold text-blue-600 hover:underline"
                >
                  <Plus className="h-3 w-3" /> Add New Account
                </button>
              )}
            </div>

            {isAddingNewAccount ? (
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newAccountInput}
                  onChange={(e) => setNewAccountInput(e.target.value)}
                  placeholder="e.g. ACC-004 / 987654321"
                  className="flex-1 rounded-xl border border-gray-300 px-3 py-2 text-xs font-mono outline-none focus:border-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                <button
                  type="button"
                  onClick={handleAddNewSourceAccount}
                  className="rounded-xl bg-blue-600 px-3 py-2 text-xs font-bold text-white hover:bg-blue-700"
                >
                  Add
                </button>
                <button
                  type="button"
                  onClick={() => setIsAddingNewAccount(false)}
                  className="rounded-xl border border-gray-200 px-3 py-2 text-xs text-gray-500 hover:bg-gray-50 dark:border-gray-700 dark:text-gray-300"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <select
                value={selectedSourceAccount}
                onChange={(e) => setSelectedSourceAccount(e.target.value)}
                className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs font-mono outline-none focus:border-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              >
                {userAccounts.map((acc) => (
                  <option key={acc} value={acc}>{acc}</option>
                ))}
              </select>
            )}
          </div>

          {/* Payee Selection */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">Select Payee / Merchant</label>
            <select
              {...register('payeeId')}
              className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
            >
              <option value="">Select payee…</option>
              {mockPayees.map((p) => (
                <option key={p.payeeId} value={p.payeeId}>{p.payeeName} ({p.payeeCategory})</option>
              ))}
            </select>
            {errors.payeeId && <p className="mt-1 text-xs text-red-600">{errors.payeeId.message}</p>}
          </div>

          {/* Payee Account Number */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">Payee Account Number</label>
            <input
              {...register('payeeAccountNumber')}
              type="text"
              placeholder="e.g. ACC-908123 / 9876543210"
              className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs font-mono outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
            />
            {errors.payeeAccountNumber && <p className="mt-1 text-xs text-red-600">{errors.payeeAccountNumber.message}</p>}
          </div>

          {/* Amount */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">Amount (USD)</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">$</span>
              <input
                {...register('amount')}
                type="number"
                step="any"
                placeholder="150.00"
                className="w-full rounded-xl border border-gray-300 py-2 pl-7 pr-3 text-xs outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              />
            </div>
            {errors.amount && <p className="mt-1 text-xs text-red-600">{errors.amount.message}</p>}
          </div>

          {/* Description */}
          <div>
            <label className="mb-1 block text-xs font-semibold text-gray-700 dark:text-gray-300">
              Note <span className="text-gray-400 font-normal">(optional)</span>
            </label>
            <input
              {...register('description')}
              type="text"
              placeholder="e.g. Vendor invoice payment"
              className="w-full rounded-xl border border-gray-300 px-3 py-2 text-xs outline-none focus:border-hawk-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
            />
          </div>

          <button
            type="submit"
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-hawk-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-hawk-700 transition"
          >
            <Send className="h-4 w-4" />
            Review DEBIT Transaction
          </button>
        </form>
      </div>
    </div>
  );
}

/**
 * AdminDashboard — matches the TMAS reference design exactly.
 * 4 rows:
 *  Row 1 – 6 KPI cards (each with sparkline mini-chart)
 *  Row 2 – Transaction Trend | Alerts by Severity donut | Alerts by Status donut
 *  Row 3 – Recent High Severity Alerts | Top Triggered Rules | System Health
 *  Row 4 – Transaction Volume Overview (area) | Monthly Fraud Trend (bar+line) | Real-time Activity Feed
 */
import { useState, useEffect, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useNavigate, Link } from 'react-router-dom';
import {
  LineChart, Line, AreaChart, Area,
  Bar, ComposedChart,
  XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, PieChart, Pie, Cell,
} from 'recharts';
import {
  Activity, AlertTriangle, ShieldCheck, CheckCircle2,
  TrendingUp, TrendingDown,
  Database, Cpu, Bell, Shield,
  ChevronRight, ClipboardList,
  Calendar,
} from 'lucide-react';
import { getAlerts, getAlertStats } from '@/lib/api/alerts';
import { getTransactions }          from '@/lib/api/transactions';
import { getRules }                 from '@/lib/api/rules';
import type { Alert, Rule, TransactionResponse } from '@/lib/types';
import dayjs from 'dayjs';

/* ── colour constants ─────────────────────────────────────────────────────── */
const SEV_CLR: Record<string, string> = {
  HIGH: '#ef4444', MEDIUM: '#f59e0b', LOW: '#22c55e',
  CRITICAL: '#8b5cf6', INFORMATIONAL: '#3b82f6',
};
const STA_CLR: Record<string, string> = {
  OPEN: '#3b82f6', ACKNOWLEDGED: '#f59e0b', INVESTIGATING: '#8b5cf6',
  CLOSED: '#22c55e', DISMISSED: '#9ca3af',
};
const RULE_CLR = ['#ef4444', '#f59e0b', '#22c55e', '#3b82f6', '#8b5cf6'];

/* ── helpers ──────────────────────────────────────────────────────────────── */
function fmt(iso: string) {
  const diff = dayjs().diff(dayjs(iso), 'minute');
  if (diff < 1)   return 'Just now';
  if (diff < 60)  return dayjs(iso).format('HH:mm A');
  if (diff < 1440)return dayjs(iso).format('HH:mm A');
  if (diff < 2880)return 'Yesterday';
  return dayjs(iso).format('MMM D, YYYY');
}

type PagedChunk<T> = {
  content: T[];
  totalPages: number;
  last: boolean;
};

async function fetchAllPages<T>(
  fetchPage: (page: number, size: number) => Promise<PagedChunk<T>>,
  size = 100,
  maxPages = 10,
) {
  const items: T[] = [];
  for (let page = 0; page < maxPages; page += 1) {
    const result = await fetchPage(page, size);
    items.push(...result.content);
    if (result.last || page >= result.totalPages - 1) {
      break;
    }
  }
  return items;
}

function fmtAxisCount(value: number) {
  if (Math.abs(value) >= 1000) {
    return `${(value / 1000).toFixed(value >= 10000 ? 0 : 1)}k`;
  }
  return `${value}`;
}

function queryStatus(isSuccess: boolean, isError: boolean): 'Healthy' | 'Degraded' | 'Checking' {
  if (isSuccess) return 'Healthy';
  if (isError) return 'Degraded';
  return 'Checking';
}

/* ── Sparkline inside KPI card ────────────────────────────────────────────── */
function Sparkline({ data, color }: { data: number[]; color: string }) {
  const pts = data.map((v, i) => ({ x: i, y: v }));
  return (
    <ResponsiveContainer width="100%" height={40}>
      <LineChart data={pts} margin={{ top: 4, right: 0, left: 0, bottom: 0 }}>
        <Line type="monotone" dataKey="y" stroke={color} strokeWidth={1.5}
              dot={false} />
      </LineChart>
    </ResponsiveContainer>
  );
}

/* ── KPI card ─────────────────────────────────────────────────────────────── */
interface KpiProps {
  title: string; value: string | number; sub: string;
  trend?: number; trendUp?: boolean;
  icon: React.ReactNode; iconBg: string; iconClr: string;
  spark: number[]; sparkColor: string;
  onClick?: () => void;
}
function KpiCard({ title, value, sub, trend, trendUp, icon, iconBg, iconClr, spark, sparkColor, onClick }: KpiProps) {
  return (
    <div onClick={onClick}
      className={`flex flex-col rounded-2xl border border-gray-100 bg-white shadow-sm
                  transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md
                  dark:border-gray-700 dark:bg-gray-900
                  ${onClick ? 'cursor-pointer' : ''}`}
    >
      <div className="flex items-start gap-3 p-4 pb-2">
        <div className={`flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl ${iconBg}`}>
          <span className={iconClr}>{icon}</span>
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-[11px] font-medium text-gray-500 dark:text-gray-400">{title}</p>
          <p className="mt-0.5 text-2xl font-black text-gray-900 dark:text-white">{value}</p>
          <p className="mt-0.5 text-[10px] text-gray-400">{sub}</p>
          {trend !== undefined && (
            <div className={`mt-1 flex items-center gap-0.5 text-[10px] font-semibold ${trendUp ? 'text-emerald-600' : 'text-red-500'}`}>
              {trendUp ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
              {Math.abs(trend)}% from last week
            </div>
          )}
        </div>
      </div>
      <div className="px-0 pb-0">
        <Sparkline data={spark} color={sparkColor} />
      </div>
    </div>
  );
}

/* ── Donut centre label ───────────────────────────────────────────────────── */
function DonutCentre({ cx, cy, total }: { cx: number; cy: number; total: number }) {
  return (
    <text x={cx} y={cy} textAnchor="middle" dominantBaseline="middle">
      <tspan x={cx} dy="-8" fontSize="24" fontWeight="900" fill="#111827">{total}</tspan>
      <tspan x={cx} dy="22" fontSize="10" fill="#9ca3af">Total</tspan>
    </text>
  );
}

/* ── System health row ────────────────────────────────────────────────────── */
function SvcRow({
  name,
  icon,
  status,
  detail,
}: {
  name: string;
  icon: React.ReactNode;
  status: 'Healthy' | 'Degraded' | 'Checking';
  detail?: string;
}) {
  const badgeClasses = status === 'Healthy'
    ? 'bg-emerald-50 text-emerald-700'
    : status === 'Degraded'
      ? 'bg-red-50 text-red-700'
      : 'bg-gray-100 text-gray-500';

  return (
    <div className="flex items-center justify-between py-2 border-b border-gray-50 dark:border-gray-800 last:border-0">
      <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
        <span className="text-gray-400">{icon}</span>
        <div>
          <span className="font-medium">{name}</span>
          {detail && <p className="text-[11px] text-gray-400">{detail}</p>}
        </div>
      </div>
      <span className={`rounded-full px-2.5 py-0.5 text-[11px] font-bold ${badgeClasses}`}>{status}</span>
    </div>
  );
}

/* ── Activity feed item ───────────────────────────────────────────────────── */
interface FeedItem { icon: React.ReactNode; iconBg: string; text: string; ref: string; time: string; }

/* ── Section header ───────────────────────────────────────────────────────── */
function SectionHeader({ title, linkTo, linkLabel = 'View All' }: { title: string; linkTo: string; linkLabel?: string }) {
  return (
    <div className="mb-3 flex items-center justify-between">
      <h2 className="text-sm font-bold text-gray-900 dark:text-white">{title}</h2>
      <Link to={linkTo} className="flex items-center gap-0.5 text-xs font-semibold text-blue-600 hover:underline">
        {linkLabel} <ChevronRight className="h-3 w-3" />
      </Link>
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════════════ */
export default function AdminDashboard() {
  const navigate = useNavigate();
  const [trendPeriod, setTrendPeriod]     = useState<'Daily' | 'Weekly'>('Daily');
  const [volPeriod,   setVolPeriod]       = useState<'Weekly' | 'Monthly'>('Weekly');
  const [fraudPeriod, setFraudPeriod]     = useState<'Monthly' | 'Yearly'>('Monthly');
  const [, setNow] = useState(dayjs());

  // Tick clock every 30 s so feed timestamps refresh
  useEffect(() => {
    const id = setInterval(() => setNow(dayjs()), 30_000);
    return () => clearInterval(id);
  }, []);

  /* ── API queries ─────────────────────────────────────────────────────── */
  const txSummaryQuery = useQuery({
    queryKey: ['txns', 'summary-db'],
    queryFn: () => getTransactions({ size: 1 }),
    refetchInterval: 10000,
  });
  const transactionsQuery = useQuery({
    queryKey: ['txns', 'dashboard-db'],
    queryFn: () => fetchAllPages<TransactionResponse>((page, size) => getTransactions({ page, size, sort: 'timestamp,desc' })),
    refetchInterval: 10000,
  });
  const rulesQuery = useQuery({
    queryKey: ['rules', 'dashboard-db'],
    queryFn: () => fetchAllPages<Rule>((page, size) => getRules({ page, size })),
    refetchInterval: 10000,
  });
  const alertsQuery = useQuery({
    queryKey: ['alerts', 'dashboard-db'],
    queryFn: () => fetchAllPages<Alert>((page, size) => getAlerts({ page, size })),
    refetchInterval: 10000,
  });
  const { data: alertStats } = useQuery({ queryKey: ['alerts', 'stats-db'], queryFn: getAlertStats, refetchInterval: 10000 });

  const transactionsRows = transactionsQuery.data ?? [];
  const rulesRows = rulesQuery.data ?? [];
  const alertsRows = alertsQuery.data ?? [];

  /* ── Derived counts ──────────────────────────────────────────────────── */
  const totalTx = txSummaryQuery.data?.totalElements ?? transactionsRows.length;
  const totalAlrts = alertStats?.total ?? alertsRows.length;
  const totalHigh = (alertStats?.bySeverity?.HIGH ?? 0) + (alertStats?.bySeverity?.CRITICAL ?? 0);
  const totalClosed = alertStats?.closed ?? 0;
  const totalInvest = alertStats?.investigating ?? 0;
  const actRules = rulesRows.filter((rule) => rule.status === 'ACTIVE').length;
  const inactRulesC = rulesRows.filter((rule) => rule.status === 'INACTIVE').length;

  /* ── Donut slices — built from flat backend AlertStatsResponseDTO fields ── */
  const sevData = alertStats?.bySeverity
    ? Object.entries(alertStats.bySeverity)
        .map(([k, v]) => ({ name: k, value: v as number }))
        .filter((d) => d.value > 0)
    : [];
  const staData = alertStats
    ? [
        { name: 'OPEN', value: alertStats.open },
        { name: 'ACKNOWLEDGED', value: alertStats.acknowledged },
        { name: 'INVESTIGATING', value: alertStats.investigating },
        { name: 'CLOSED', value: alertStats.closed },
        { name: 'DISMISSED', value: alertStats.dismissed },
      ].filter((d) => d.value > 0)
    : [];
  const sevTotal = sevData.reduce((s, d) => s + d.value, 0);
  const staTotal = staData.reduce((s, d) => s + d.value, 0);

  /* ── Trend data (transactions + alerts combined) ─────────────────────── */
  const trendData = useMemo(() => {
    if (trendPeriod === 'Weekly') {
      const weeks = Array.from({ length: 6 }, (_, idx) => dayjs().startOf('week').subtract(5 - idx, 'week'));
      return weeks.map((weekStart) => {
        const weekEnd = weekStart.endOf('week');
        return {
          date: weekStart.format('MMM D'),
          count: transactionsRows.filter((txn) => {
            const ts = dayjs(txn.timestamp);
            return ts.isValid() && (ts.isAfter(weekStart) || ts.isSame(weekStart)) && (ts.isBefore(weekEnd) || ts.isSame(weekEnd));
          }).length,
          alerts: alertsRows.filter((alert) => {
            const ts = dayjs(alert.createdAt);
            return ts.isValid() && (ts.isAfter(weekStart) || ts.isSame(weekStart)) && (ts.isBefore(weekEnd) || ts.isSame(weekEnd));
          }).length,
        };
      });
    }

    const days = Array.from({ length: 7 }, (_, idx) => dayjs().startOf('day').subtract(6 - idx, 'day'));
    return days.map((dayStart) => {
      const dayEnd = dayStart.endOf('day');
      return {
        date: dayStart.format('MMM D'),
        count: transactionsRows.filter((txn) => {
          const ts = dayjs(txn.timestamp);
          return ts.isValid() && (ts.isAfter(dayStart) || ts.isSame(dayStart)) && (ts.isBefore(dayEnd) || ts.isSame(dayEnd));
        }).length,
        alerts: alertsRows.filter((alert) => {
          const ts = dayjs(alert.createdAt);
          return ts.isValid() && (ts.isAfter(dayStart) || ts.isSame(dayStart)) && (ts.isBefore(dayEnd) || ts.isSame(dayEnd));
        }).length,
      };
    });
  }, [alertsRows, transactionsRows, trendPeriod]);

  /* ── Volume area data ─────────────────────────────────────────────────── */
  const volData = useMemo(() => {
    if (volPeriod === 'Monthly') {
      const months = Array.from({ length: 6 }, (_, idx) => dayjs().startOf('month').subtract(5 - idx, 'month'));
      return months.map((monthStart) => {
        const monthEnd = monthStart.endOf('month');
        return {
          date: monthStart.format('MMM'),
          count: transactionsRows.filter((txn) => {
            const ts = dayjs(txn.timestamp);
            return ts.isValid() && (ts.isAfter(monthStart) || ts.isSame(monthStart)) && (ts.isBefore(monthEnd) || ts.isSame(monthEnd));
          }).length,
        };
      });
    }

    const days = Array.from({ length: 7 }, (_, idx) => dayjs().startOf('day').subtract(6 - idx, 'day'));
    return days.map((dayStart) => {
      const dayEnd = dayStart.endOf('day');
      return {
        date: dayStart.format('MMM D'),
        count: transactionsRows.filter((txn) => {
          const ts = dayjs(txn.timestamp);
          return ts.isValid() && (ts.isAfter(dayStart) || ts.isSame(dayStart)) && (ts.isBefore(dayEnd) || ts.isSame(dayEnd));
        }).length,
      };
    });
  }, [transactionsRows, volPeriod]);

  /* ── Fraud trend (bar = high severity, line = total) ─────────────────── */
  const fraudData = useMemo(() => {
    const highSeverity = new Set(['HIGH', 'CRITICAL']);

    if (fraudPeriod === 'Yearly') {
      const years = Array.from({ length: 5 }, (_, idx) => dayjs().startOf('year').subtract(4 - idx, 'year'));
      return years.map((yearStart) => {
        const yearEnd = yearStart.endOf('year');
        const alertsInWindow = alertsRows.filter((alert) => {
          const ts = dayjs(alert.createdAt);
          return ts.isValid() && (ts.isAfter(yearStart) || ts.isSame(yearStart)) && (ts.isBefore(yearEnd) || ts.isSame(yearEnd));
        });
        return {
          month: yearStart.format('YYYY'),
          high: alertsInWindow.filter((alert) => highSeverity.has(alert.severity)).length,
          total: alertsInWindow.length,
        };
      });
    }

    const months = Array.from({ length: 6 }, (_, idx) => dayjs().startOf('month').subtract(5 - idx, 'month'));
    return months.map((monthStart) => {
      const monthEnd = monthStart.endOf('month');
      const alertsInWindow = alertsRows.filter((alert) => {
        const ts = dayjs(alert.createdAt);
        return ts.isValid() && (ts.isAfter(monthStart) || ts.isSame(monthStart)) && (ts.isBefore(monthEnd) || ts.isSame(monthEnd));
      });
      return {
        month: monthStart.format('MMM'),
        high: alertsInWindow.filter((alert) => highSeverity.has(alert.severity)).length,
        total: alertsInWindow.length,
      };
    });
  }, [alertsRows, fraudPeriod]);

  /* ── Top rules ────────────────────────────────────────────────────────── */
  const topRules = useMemo(() => {
    const counts = new Map<string, number>();
    rulesRows.forEach((rule) => counts.set(rule.ruleName, 0));
    alertsRows.forEach((alert) => {
      const ruleName = alert.ruleName || `Rule #${alert.ruleId}`;
      counts.set(ruleName, (counts.get(ruleName) ?? 0) + 1);
    });

    return Array.from(counts.entries())
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name))
      .slice(0, 5);
  }, [alertsRows, rulesRows]);
  const maxRule = Math.max(1, ...topRules.map((rule) => rule.count));

  /* ── Recent alerts list ───────────────────────────────────────────────── */
  const recentList = useMemo(
    () => [...alertsRows].sort((a, b) => dayjs(b.createdAt).valueOf() - dayjs(a.createdAt).valueOf()).slice(0, 5),
    [alertsRows],
  );

  /* ── Real-time activity feed ──────────────────────────────────────────── */
  const feed: FeedItem[] = useMemo(() => {
    const alertItems = alertsRows.slice(0, 5).map((alert) => ({
      iconBg: alert.severity === 'HIGH' || alert.severity === 'CRITICAL' ? 'bg-red-50' : 'bg-amber-50',
      icon: <AlertTriangle className={`h-3.5 w-3.5 ${alert.severity === 'HIGH' || alert.severity === 'CRITICAL' ? 'text-red-500' : 'text-amber-500'}`} />,
      text: `${alert.ruleName || 'Alert'} created`,
      ref: `ALERT-${alert.alertId}`,
      time: alert.createdAt,
    }));

    const transactionItems = transactionsRows.slice(0, 5).map((txn) => ({
      iconBg: 'bg-blue-50',
      icon: <Activity className="h-3.5 w-3.5 text-blue-500" />,
      text: `Transaction from ${txn.accountId} to ${txn.payeeName}`,
      ref: `TXN-${txn.transactionId}`,
      time: txn.timestamp || txn.createdAt,
    }));

    const ruleItems = rulesRows.slice(0, 5).map((rule) => ({
      iconBg: 'bg-emerald-50',
      icon: <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" />,
      text: `${rule.ruleName} (${rule.status.toLowerCase()})`,
      ref: `RULE-${rule.ruleId}`,
      time: rule.updatedAt,
    }));

    return [...alertItems, ...transactionItems, ...ruleItems]
      .sort((a, b) => dayjs(b.time).valueOf() - dayjs(a.time).valueOf())
      .slice(0, 5);
  }, [alertsRows, transactionsRows, rulesRows]);

  const systemStatuses = {
    database: queryStatus(txSummaryQuery.isSuccess && alertsQuery.isSuccess && rulesQuery.isSuccess, txSummaryQuery.isError || alertsQuery.isError || rulesQuery.isError),
    transactions: queryStatus(transactionsQuery.isSuccess, transactionsQuery.isError),
    rules: queryStatus(rulesQuery.isSuccess, rulesQuery.isError),
    alerts: queryStatus(alertsQuery.isSuccess && Boolean(alertStats), alertsQuery.isError),
  };

  /* ── Sparkline seeds ──────────────────────────────────────────────────── */
  const txSpark   = [3200,3800,3100,4200,4700,4100,4400];
  const altSpark  = [280,320,290,350,400,360,328];
  const hiSpark   = [55,62,58,70,80,72,67];
  const clsSpark  = [230,248,260,270,255,268,261];
  const ruleSpark = [20,22,21,23,24,22,24];
  const invSpark  = [35,38,40,44,48,45,42];

  /* ── Tooltip style ────────────────────────────────────────────────────── */
  const ttStyle = { fontSize: 11, borderRadius: 8, border: '1px solid #e5e7eb', padding: '6px 10px' };

  /* ── Period picker ────────────────────────────────────────────────────── */
  function PeriodPicker({ value, onChange, options }: { value: string; onChange: (v: string) => void; options: string[] }) {
    return (
      <select value={value} onChange={e => onChange(e.target.value)}
        className="rounded-lg border border-gray-200 bg-gray-50 px-2 py-1 text-xs font-medium text-gray-600 focus:outline-none dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300">
        {options.map(o => <option key={o}>{o}</option>)}
      </select>
    );
  }

  /* ── Legend row for donuts ────────────────────────────────────────────── */
  function LegendRow({ name, value, total, color }: { name: string; value: number; total: number; color: string }) {
    const pct = total > 0 ? ((value / total) * 100).toFixed(1) : '0';
    return (
      <div className="flex items-center justify-between gap-2 py-0.5 text-xs">
        <div className="flex items-center gap-1.5">
          <span className="h-2.5 w-2.5 flex-shrink-0 rounded-sm" style={{ backgroundColor: color }} />
          <span className="text-gray-600 dark:text-gray-400 capitalize">{name.charAt(0) + name.slice(1).toLowerCase()}</span>
        </div>
        <span className="font-semibold text-gray-800 dark:text-white">{value} <span className="font-normal text-gray-400">({pct}%)</span></span>
      </div>
    );
  }

  return (
    <div className="space-y-5">

      {/* ── Page Header ─────────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-black text-gray-900 dark:text-white">Dashboard</h1>
          <p className="text-xs text-gray-500 dark:text-gray-400">Welcome back, Admin! Here's what's happening in the system today.</p>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 rounded-xl border border-gray-200 bg-white px-3 py-2 text-xs text-gray-600 shadow-sm dark:border-gray-700 dark:bg-gray-900">
            <Calendar className="h-3.5 w-3.5 text-gray-400" />
            {dayjs().subtract(6,'day').format('MMM D, YYYY')} – {dayjs().format('MMM D, YYYY')}
          </div>
        </div>
      </div>

      {/* ══ ROW 1 — KPI CARDS ══════════════════════════════════════════════ */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-3 xl:grid-cols-6">

        <KpiCard title="Total Transactions" value={totalTx.toLocaleString()} sub="All time"
          trend={15.8} trendUp icon={<Activity className="h-4 w-4" />}
          iconBg="bg-blue-50" iconClr="text-blue-600"
          spark={txSpark} sparkColor="#2563eb"
          onClick={() => navigate('/admin/metrics')} />

        <KpiCard title="Total Alerts" value={totalAlrts.toLocaleString()} sub="Generated"
          trend={22.4} trendUp icon={<AlertTriangle className="h-4 w-4" />}
          iconBg="bg-red-50" iconClr="text-red-600"
          spark={altSpark} sparkColor="#ef4444"
          onClick={() => navigate('/alerts')} />

        <KpiCard title="High Severity Alerts" value={totalHigh} sub="Needs action"
          trend={12.1} trendUp={false} icon={<Bell className="h-4 w-4" />}
          iconBg="bg-orange-50" iconClr="text-orange-500"
          spark={hiSpark} sparkColor="#f59e0b"
          onClick={() => navigate('/alerts?severity=HIGH')} />

        <KpiCard title="Closed Alerts" value={totalClosed} sub="Resolved"
          trend={10.1} trendUp icon={<CheckCircle2 className="h-4 w-4" />}
          iconBg="bg-emerald-50" iconClr="text-emerald-600"
          spark={clsSpark} sparkColor="#22c55e"
          onClick={() => navigate('/alerts/history')} />

        <KpiCard title="Active Rules" value={actRules}
          sub={`${actRules} Active • ${inactRulesC} Inactive`}
          icon={<ShieldCheck className="h-4 w-4" />}
          iconBg="bg-indigo-50" iconClr="text-indigo-600"
          spark={ruleSpark} sparkColor="#6366f1"
          onClick={() => navigate('/admin/rules')} />

        <KpiCard title="Open Investigations" value={totalInvest}
          sub={`32 High • 10 Medium`}
          icon={<ClipboardList className="h-4 w-4" />}
          iconBg="bg-purple-50" iconClr="text-purple-600"
          spark={invSpark} sparkColor="#8b5cf6"
          onClick={() => navigate('/alerts?status=INVESTIGATING')} />
      </div>

      {/* ══ ROW 2 — TREND | SEVERITY DONUT | STATUS DONUT ══════════════════ */}
      <div className="grid grid-cols-1 gap-4 xl:grid-cols-3">

        {/* Transaction Trend */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <div className="mb-3 flex items-center justify-between">
            <h2 className="text-sm font-bold text-gray-900 dark:text-white">Transaction Trend</h2>
            <PeriodPicker value={trendPeriod} onChange={v => setTrendPeriod(v as 'Daily'|'Weekly')} options={['Daily','Weekly']} />
          </div>
          <div className="mb-2 flex gap-4 text-xs text-gray-500">
            <span className="flex items-center gap-1.5"><span className="inline-block h-0.5 w-5 rounded bg-blue-500" />Transactions</span>
            <span className="flex items-center gap-1.5"><span className="inline-block h-0.5 w-5 rounded bg-red-400" />Alerts</span>
          </div>
          <ResponsiveContainer width="100%" height={200}>
            <LineChart data={trendData} margin={{ top:4, right:4, left:-20, bottom:0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="date" tick={{ fontSize:10, fill:'#9ca3af' }} />
              <YAxis tick={{ fontSize:10, fill:'#9ca3af' }} />
              <Tooltip contentStyle={ttStyle} />
              <Line type="monotone" dataKey="count"  stroke="#2563eb" strokeWidth={2} dot={{ r:3,fill:'#2563eb' }} name="Transactions" />
              <Line type="monotone" dataKey="alerts" stroke="#ef4444" strokeWidth={2} dot={{ r:3,fill:'#ef4444' }} name="Alerts" />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* Alerts by Severity donut */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <h2 className="mb-3 text-sm font-bold text-gray-900 dark:text-white">Alerts by Severity</h2>
          <div className="flex items-center gap-4">
            <div className="flex-shrink-0">
              <PieChart width={150} height={150}>
                <Pie data={sevData} cx={71} cy={71} innerRadius={48} outerRadius={68}
                     paddingAngle={2} dataKey="value" startAngle={90} endAngle={-270}>
                  {sevData.map(e => <Cell key={e.name} fill={SEV_CLR[e.name] ?? '#d1d5db'} />)}
                </Pie>
                <DonutCentre cx={71} cy={71} total={sevTotal} />
              </PieChart>
            </div>
            <div className="flex-1 space-y-1">
              {sevData.map(d => (
                <LegendRow key={d.name} name={d.name} value={d.value} total={sevTotal} color={SEV_CLR[d.name] ?? '#d1d5db'} />
              ))}
            </div>
          </div>
        </div>

        {/* Alerts by Status donut */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <h2 className="mb-3 text-sm font-bold text-gray-900 dark:text-white">Alerts by Status</h2>
          <div className="flex items-center gap-4">
            <div className="flex-shrink-0">
              <PieChart width={150} height={150}>
                <Pie data={staData} cx={71} cy={71} innerRadius={48} outerRadius={68}
                     paddingAngle={2} dataKey="value" startAngle={90} endAngle={-270}>
                  {staData.map(e => <Cell key={e.name} fill={STA_CLR[e.name] ?? '#d1d5db'} />)}
                </Pie>
                <DonutCentre cx={71} cy={71} total={staTotal} />
              </PieChart>
            </div>
            <div className="flex-1 space-y-1">
              {staData.map(d => (
                <LegendRow key={d.name} name={d.name} value={d.value} total={staTotal} color={STA_CLR[d.name] ?? '#d1d5db'} />
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* ══ ROW 3 — RECENT ALERTS | TOP RULES | SYSTEM HEALTH ══════════════ */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">

        {/* Recent Alerts */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <SectionHeader title="Recent Alerts" linkTo="/alerts" />
          <div className="space-y-0.5">
            {recentList.slice(0,5).map((a) => (
              <div key={a.alertId} onClick={() => navigate(`/alerts/${a.alertId}`)}
                className="flex cursor-pointer items-center gap-3 rounded-xl px-2 py-2 hover:bg-gray-50 dark:hover:bg-gray-800 transition">
                <span className="mt-0.5 h-2 w-2 flex-shrink-0 rounded-full bg-red-500" />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-xs font-medium text-gray-800 dark:text-gray-200">{a.alertMessage}</p>
                </div>
                <div className="flex-shrink-0 text-right">
                  <p className="text-[10px] font-mono text-gray-500">TXN-{a.transactionId}</p>
                  <p className="text-[10px] text-gray-400">{fmt(a.createdAt)}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Top Triggered Rules */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <SectionHeader title="Top Triggered Rules" linkTo="/admin/rules" />
          <div className="space-y-3">
            {topRules.length === 0 && (
              <p className="text-xs text-gray-400">No rule activity found yet.</p>
            )}
            {topRules.map((r, idx) => {
              const pct   = ((r.count / maxRule) * 100).toFixed(0);
              const color = RULE_CLR[idx % RULE_CLR.length];
              return (
                <div key={r.name}>
                  <div className="mb-1 flex items-center justify-between text-xs">
                    <span className="font-medium text-gray-700 dark:text-gray-300">{r.name}</span>
                    <span className="font-bold text-gray-900 dark:text-white">{r.count}</span>
                  </div>
                  <div className="h-2 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-gray-800">
                    <div className="h-full rounded-full transition-all duration-700"
                         style={{ width: `${pct}%`, backgroundColor: color }} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* System Health */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <h2 className="mb-3 text-sm font-bold text-gray-900 dark:text-white">System Health</h2>
          <SvcRow name="Database" icon={<Database className="h-4 w-4" />} status={systemStatuses.database} detail={`${totalTx} tx • ${totalAlrts} alerts`} />
          <SvcRow name="Transaction Service" icon={<Activity className="h-4 w-4" />} status={systemStatuses.transactions} detail={`${totalTx} records loaded`} />
          <SvcRow name="Rule Engine Service" icon={<Cpu className="h-4 w-4" />} status={systemStatuses.rules} detail={`${actRules} active rules`} />
          <SvcRow name="Alert Service" icon={<Bell className="h-4 w-4" />} status={systemStatuses.alerts} detail={`${totalAlrts} total alerts`} />
          <SvcRow name="Monitoring Rules Service" icon={<Shield className="h-4 w-4" />} status={systemStatuses.rules} detail={`${rulesRows.length} rules visible`} />
        </div>
      </div>

      {/* ══ ROW 4 — VOLUME AREA | FRAUD TREND | ACTIVITY FEED ══════════════ */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">

        {/* Transaction Volume Overview — area chart */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <div className="mb-3 flex items-center justify-between">
            <h2 className="text-sm font-bold text-gray-900 dark:text-white">Transaction Volume Overview</h2>
            <PeriodPicker value={volPeriod} onChange={v => setVolPeriod(v as 'Weekly'|'Monthly')} options={['Weekly','Monthly']} />
          </div>
          <ResponsiveContainer width="100%" height={180}>
            <AreaChart data={volData} margin={{ top:4, right:4, left:-20, bottom:0 }}>
              <defs>
                <linearGradient id="volGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%"  stopColor="#2563eb" stopOpacity={0.15} />
                  <stop offset="95%" stopColor="#2563eb" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="date" tick={{ fontSize:10, fill:'#9ca3af' }} />
              <YAxis tick={{ fontSize:10, fill:'#9ca3af' }} tickFormatter={(v:number) => fmtAxisCount(v)} />
              <Tooltip contentStyle={ttStyle} formatter={(v:number) => [`${v.toLocaleString()}`, 'Transactions']} />
              <Area type="monotone" dataKey="count" stroke="#2563eb" strokeWidth={2}
                    fill="url(#volGrad)" dot={{ r:3, fill:'#2563eb' }} name="Transactions" />
            </AreaChart>
          </ResponsiveContainer>
        </div>

        {/* Monthly Fraud Trend — bar + line */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <div className="mb-2 flex items-center justify-between">
            <h2 className="text-sm font-bold text-gray-900 dark:text-white">Monthly Fraud Trend</h2>
            <PeriodPicker value={fraudPeriod} onChange={v => setFraudPeriod(v as 'Monthly'|'Yearly')} options={['Monthly','Yearly']} />
          </div>
          <div className="mb-2 flex gap-4 text-xs text-gray-500">
            <span className="flex items-center gap-1.5"><span className="inline-block h-2.5 w-2.5 rounded-sm bg-red-400" />High Severity Alerts</span>
            <span className="flex items-center gap-1.5"><span className="inline-block h-0.5 w-5 rounded bg-blue-500" />Total Alerts</span>
          </div>
          <ResponsiveContainer width="100%" height={158}>
            <ComposedChart data={fraudData} margin={{ top:4, right:4, left:-20, bottom:0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
              <XAxis dataKey="month" tick={{ fontSize:10, fill:'#9ca3af' }} />
              <YAxis yAxisId="left"  tick={{ fontSize:10, fill:'#9ca3af' }} />
              <YAxis yAxisId="right" orientation="right" tick={{ fontSize:10, fill:'#9ca3af' }} />
              <Tooltip contentStyle={ttStyle} />
              <Bar  yAxisId="left"  dataKey="high"  fill="#ef4444" radius={[3,3,0,0]} name="High Severity" />
              <Line yAxisId="right" type="monotone" dataKey="total" stroke="#2563eb" strokeWidth={2} dot={{ r:3,fill:'#2563eb' }} name="Total Alerts" />
            </ComposedChart>
          </ResponsiveContainer>
        </div>

        {/* Real-time Activity Feed */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
          <SectionHeader title="Real-time Activity Feed" linkTo="/alerts" />
          <div className="space-y-0.5">
            {feed.length === 0 && <p className="px-2 py-2 text-xs text-gray-400">No recent database activity yet.</p>}
            {feed.map((item, idx) => (
              <div key={idx} className="flex items-center gap-3 rounded-xl px-2 py-2 transition hover:bg-gray-50 dark:hover:bg-gray-800">
                <div className={`flex h-7 w-7 flex-shrink-0 items-center justify-center rounded-full ${item.iconBg}`}>
                  {item.icon}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-xs font-medium text-gray-800 dark:text-gray-200">{item.text}</p>
                </div>
                <div className="flex-shrink-0 text-right">
                  <p className="text-[10px] font-mono text-gray-500">{item.ref}</p>
                  <p className="text-[10px] text-gray-400">{fmt(item.time)}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
}

/**
 * AdminDashboard — matches the TMAS reference design exactly.
 * 4 rows:
 *  Row 1 – 6 KPI cards (each with sparkline mini-chart)
 *  Row 2 – Transaction Trend | Alerts by Severity donut | Alerts by Status donut
 *  Row 3 – Recent High Severity Alerts | Top Triggered Rules | System Health
 *  Row 4 – Transaction Volume Overview (area) | Monthly Fraud Trend (bar+line) | Real-time Activity Feed
 */
import { useState, useEffect, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useNavigate, Link } from 'react-router-dom';
import {
  LineChart, Line, AreaChart, Area,
  Bar, ComposedChart,
  XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, PieChart, Pie, Cell,
} from 'recharts';
import {
  Activity, AlertTriangle, ShieldCheck, CheckCircle2,
  TrendingUp, TrendingDown,
  Database, Cpu, Bell, Shield,
  ChevronRight, ClipboardList,
  Calendar,
} from 'lucide-react';
import { getAlerts, getAlertStats } from '@/lib/api/alerts';
import { getTransactions }          from '@/lib/api/transactions';
import { getRules }                 from '@/lib/api/rules';
import type { Alert, Rule, TransactionResponse } from '@/lib/types';
import dayjs from 'dayjs';

/* ── colour constants ─────────────────────────────────────────────────────── */
const SEV_CLR: Record<string, string> = {
  HIGH: '#ef4444', MEDIUM: '#f59e0b', LOW: '#22c55e',
  CRITICAL: '#8b5cf6', INFORMATIONAL: '#3b82f6',
};
const STA_CLR: Record<string, string> = {
  OPEN: '#3b82f6', ACKNOWLEDGED: '#f59e0b', INVESTIGATING: '#8b5cf6',
  CLOSED: '#22c55e', DISMISSED: '#9ca3af',
};
const RULE_CLR = ['#ef4444', '#f59e0b', '#22c55e', '#3b82f6', '#8b5cf6'];

/* ── helpers ──────────────────────────────────────────────────────────────── */
function fmt(iso: string) {
  const diff = dayjs().diff(dayjs(iso), 'minute');
  if (diff < 1)   return 'Just now';
  if (diff < 60)  return dayjs(iso).format('HH:mm A');
  if (diff < 1440)return dayjs(iso).format('HH:mm A');
  if (diff < 2880)return 'Yesterday';
  return dayjs(iso).format('MMM D, YYYY');
}

type PagedChunk<T> = {
  content: T[];
  totalPages: number;
  last: boolean;
};

async function fetchAllPages<T>(
  fetchPage: (page: number, size: number) => Promise<PagedChunk<T>>,
  size = 100,
  maxPages = 10,
) {
  const items: T[] = [];
  for (let page = 0; page < maxPages; page += 1) {
    const result = await fetchPage(page, size);
    items.push(...result.content);
    if (result.last || page >= result.totalPages - 1) {
      break;
    }
  }
  return items;
}

function fmtAxisCount(value: number) {
  if (Math.abs(value) >= 1000) {
    return `${(value / 1000).toFixed(value >= 10000 ? 0 : 1)}k`;
  }
  return `${value}`;
}

function queryStatus(isSuccess: boolean, isError: boolean): 'Healthy' | 'Degraded' | 'Checking' {
  if (isSuccess) return 'Healthy';
  if (isError) return 'Degraded';
  return 'Checking';
}

/* ── Sparkline inside KPI card ────────────────────────────────────────────── */
function Sparkline({ data, color }: { data: number[]; color: string }) {
  const pts = data.map((v, i) => ({ x: i, y: v }));
  return (
    <ResponsiveContainer width="100%" height={40}>
      <LineChart data={pts} margin={{ top: 4, right: 0, left: 0, bottom: 0 }}>
        <Line type="monotone" dataKey="y" stroke={color} strokeWidth={1.5}
              dot={false} />
      </LineChart>
    </ResponsiveContainer>
  );
}

/* ── KPI card ─────────────────────────────────────────────────────────────── */
interface KpiProps {
  title: string; value: string | number; sub: string;
  trend?: number; trendUp?: boolean;
  icon: React.ReactNode; iconBg: string; iconClr: string;
  spark: number[]; sparkColor: string;
  onClick?: () => void;
}
function KpiCard({ title, value, sub, trend, trendUp, icon, iconBg, iconClr, spark, sparkColor, onClick }: KpiProps) {
  return (
    <div onClick={onClick}
      className={`flex flex-col rounded-2xl border border-gray-100 bg-white shadow-sm
                  transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md
                  dark:border-gray-700 dark:bg-gray-900
                  ${onClick ? 'cursor-pointer' : ''}`}
    >
      <div className="flex items-start gap-3 p-4 pb-2">
        <div className={`flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl ${iconBg}`}>
          <span className={iconClr}>{icon}</span>
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-[11px] font-medium text-gray-500 dark:text-gray-400">{title}</p>
          <p className="mt-0.5 text-2xl font-black text-gray-900 dark:text-white">{value}</p>
          <p className="mt-0.5 text-[10px] text-gray-400">{sub}</p>
          {trend !== undefined && (
            <div className={`mt-1 flex items-center gap-0.5 text-[10px] font-semibold ${trendUp ? 'text-emerald-600' : 'text-red-500'}`}>
              {trendUp ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
              {Math.abs(trend)}% from last week
            </div>
          )}
        </div>
      </div>
      <div className="px-0 pb-0">
        <Sparkline data={spark} color={sparkColor} />
      </div>
    </div>
  );
}

/* ── Donut centre label ───────────────────────────────────────────────────── */
function DonutCentre({ cx, cy, total }: { cx: number; cy: number; total: number }) {
  return (
    <text x={cx} y={cy} textAnchor="middle" dominantBaseline="middle">
      <tspan x={cx} dy="-8" fontSize="24" fontWeight="900" fill="#111827">{total}</tspan>
      <tspan x={cx} dy="22" fontSize="10" fill="#9ca3af">Total</tspan>
    </text>
  );
}

/* ── System health row ────────────────────────────────────────────────────── */
function SvcRow({
  name,
  icon,
  status,
  detail,
}: {
  name: string;
  icon: React.ReactNode;
  status: 'Healthy' | 'Degraded' | 'Checking';
  detail?: string;
}) {
  const badgeClasses = status === 'Healthy'
    ? 'bg-emerald-50 text-emerald-700'
    : status === 'Degraded'
      ? 'bg-red-50 text-red-700'
      : 'bg-gray-100 text-gray-500';

  return (
    <div className="flex items-center justify-between py-2 border-b border-gray-50 dark:border-gray-800 last:border-0">
      <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
        <span className="text-gray-400">{icon}</span>
        <div>
          <span className="font-medium">{name}</span>
          {detail && <p className="text-[11px] text-gray-400">{detail}</p>}
        </div>
      </div>
      <span className={`rounded-full px-2.5 py-0.5 text-[11px] font-bold ${badgeClasses}`}>{status}</span>
    </div>
  );
}

/* ── Activity feed item ───────────────────────────────────────────────────── */
interface FeedItem { icon: React.ReactNode; iconBg: string; text: string; ref: string; time: string; }

/* ── Section header ───────────────────────────────────────────────────────── */
function SectionHeader({ title, linkTo, linkLabel = 'View All' }: { title: string; linkTo: string; linkLabel?: string }) {
  return (
    <div className="mb-3 flex items-center justify-between">
      <h2 className="text-sm font-bold text-gray-900 dark:text-white">{title}</h2>
      <Link to={linkTo} className="flex items-center gap-0.5 text-xs font-semibold text-blue-600 hover:underline">
        {linkLabel} <ChevronRight className="h-3 w-3" />
      </Link>
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════════════ */
export default function AdminDashboard() {
  const navigate = useNavigate();
  const [trendPeriod, setTrendPeriod]     = useState<'Daily' | 'Weekly'>('Daily');
  const [volPeriod,   setVolPeriod]       = useState<'Weekly' | 'Monthly'>('Weekly');
  const [fraudPeriod, setFraudPeriod]     = useState<'Monthly' | 'Yearly'>('Monthly');
  const [startDate, setStartDate] = useState(dayjs().subtract(6, 'day').format('YYYY-MM-DD'));
  const [endDate, setEndDate] = useState(dayjs().format('YYYY-MM-DD'));
  const [, setNow] = useState(dayjs());

  const calendarStartIso = dayjs(startDate).startOf('day').format('YYYY-MM-DDTHH:mm:ss');
  const calendarEndIso = dayjs(endDate).endOf('day').format('YYYY-MM-DDTHH:mm:ss');

  // Tick clock every 30 s so feed timestamps refresh
  useEffect(() => {
    const id = setInterval(() => setNow(dayjs()), 30_000);
    return () => clearInterval(id);
  }, []);

  /* ── API queries ─────────────────────────────────────────────────────── */
  const txSummaryQuery = useQuery({
    queryKey: ['txns', 'summary-db', startDate, endDate],
    queryFn: () => getTransactions({ size: 1, startDate: calendarStartIso, endDate: calendarEndIso }),
    refetchInterval: 10000,
  });
  const transactionsQuery = useQuery({
    queryKey: ['txns', 'dashboard-db', startDate, endDate],
    queryFn: () => fetchAllPages<TransactionResponse>((page, size) => getTransactions({
      page,
      size,
      sort: 'timestamp,desc',
      startDate: calendarStartIso,
      endDate: calendarEndIso,
    })),
    refetchInterval: 10000,
  });
  const rulesQuery = useQuery({
    queryKey: ['rules', 'dashboard-db'],
    queryFn: () => fetchAllPages<Rule>((page, size) => getRules({ page, size })),
    refetchInterval: 10000,
  });
  const alertsQuery = useQuery({
    queryKey: ['alerts', 'dashboard-db'],
    queryFn: () => fetchAllPages<Alert>((page, size) => getAlerts({ page, size })),
    refetchInterval: 10000,
  });
  const { data: alertStats } = useQuery({ queryKey: ['alerts', 'stats-db'], queryFn: getAlertStats, refetchInterval: 10000 });

  const transactionsRows = transactionsQuery.data ?? [];
  const rulesRows = rulesQuery.data ?? [];
  const alertsRows = alertsQuery.data ?? [];

  /* ── Derived counts ──────────────────────────────────────────────────── */
  const totalTx = txSummaryQuery.data?.totalElements ?? transactionsRows.length;
  const totalAlrts = alertStats?.total ?? alertsRows.length;
  const totalHigh = (alertStats?.bySeverity?.HIGH ?? 0) + (alertStats?.bySeverity?.CRITICAL ?? 0);
  const totalClosed = alertStats?.closed ?? 0;
  const totalInvest = alertStats?.investigating ?? 0;
  const actRules = rulesRows.filter((rule) => rule.status === 'ACTIVE').length;
  const inactRulesC = rulesRows.filter((rule) => rule.status === 'INACTIVE').length;

  /* ── Donut slices — built from flat backend AlertStatsResponseDTO fields ── */
  const sevData = alertStats?.bySeverity
    ? Object.entries(alertStats.bySeverity)
        .map(([k, v]) => ({ name: k, value: v as number }))
        .filter((d) => d.value > 0)
    : [];
  const staData = alertStats
    ? [
        { name: 'OPEN', value: alertStats.open },
        { name: 'ACKNOWLEDGED', value: alertStats.acknowledged },
        { name: 'INVESTIGATING', value: alertStats.investigating },
        { name: 'CLOSED', value: alertStats.closed },
        { name: 'DISMISSED', value: alertStats.dismissed },
      ].filter((d) => d.value > 0)
    : [];
  const sevTotal = sevData.reduce((s, d) => s + d.value, 0);
  const staTotal = staData.reduce((s, d) => s + d.value, 0);

  /* ── Trend data (transactions + alerts combined) ─────────────────────── */
  const trendData = useMemo(() => {
    if (trendPeriod === 'Weekly') {
      const weeks = Array.from({ length: 6 }, (_, idx) => dayjs().startOf('week').subtract(5 - idx, 'week'));
      return weeks.map((weekStart) => {
        const weekEnd = weekStart.endOf('week');
        return {
          date: weekStart.format('MMM D'),
          count: transactionsRows.filter((txn) => {
            const ts = dayjs(txn.timestamp);
            return ts.isValid() && (ts.isAfter(weekStart) || ts.isSame(weekStart)) && (ts.isBefore(weekEnd) || ts.isSame(weekEnd));
          }).length,
          alerts: alertsRows.filter((alert) => {
            const ts = dayjs(alert.createdAt);
            return ts.isValid() && (ts.isAfter(weekStart) || ts.isSame(weekStart)) && (ts.isBefore(weekEnd) || ts.isSame(weekEnd));
          }).length,
        };
      });
    }

    const days = Array.from({ length: 7 }, (_, idx) => dayjs().startOf('day').subtract(6 - idx, 'day'));
    return days.map((dayStart) => {
      const dayEnd = dayStart.endOf('day');
      return {
        date: dayStart.format('MMM D'),
        count: transactionsRows.filter((txn) => {
          const ts = dayjs(txn.timestamp);
          return ts.isValid() && (ts.isAfter(dayStart) || ts.isSame(dayStart)) && (ts.isBefore(dayEnd) || ts.isSame(dayEnd));
        }).length,
        alerts: alertsRows.filter((alert) => {
          const ts = dayjs(alert.createdAt);
          return ts.isValid() && (ts.isAfter(dayStart) || ts.isSame(dayStart)) && (ts.isBefore(dayEnd) || ts.isSame(dayEnd));
        }).length,
      };
    });
  }, [alertsRows, transactionsRows, trendPeriod]);

  /* ── Volume area data ─────────────────────────────────────────────────── */
  const volData = useMemo(() => {
    if (volPeriod === 'Monthly') {
      const months = Array.from({ length: 6 }, (_, idx) => dayjs().startOf('month').subtract(5 - idx, 'month'));
      return months.map((monthStart) => {
        const monthEnd = monthStart.endOf('month');
        return {
          date: monthStart.format('MMM'),
          count: transactionsRows.filter((txn) => {
            const ts = dayjs(txn.timestamp);
            return ts.isValid() && (ts.isAfter(monthStart) || ts.isSame(monthStart)) && (ts.isBefore(monthEnd) || ts.isSame(monthEnd));
          }).length,
        };
      });
    }

    const days = Array.from({ length: 7 }, (_, idx) => dayjs().startOf('day').subtract(6 - idx, 'day'));
    return days.map((dayStart) => {
      const dayEnd = dayStart.endOf('day');
      return {
        date: dayStart.format('MMM D'),
        count: transactionsRows.filter((txn) => {
          const ts = dayjs(txn.timestamp);
          return ts.isValid() && (ts.isAfter(dayStart) || ts.isSame(dayStart)) && (ts.isBefore(dayEnd) || ts.isSame(dayEnd));
        }).length,
      };
    });
  }, [transactionsRows, volPeriod]);

  /* ── Fraud trend (bar = high severity, line = total) ─────────────────── */
  const fraudData = useMemo(() => {
    const highSeverity = new Set(['HIGH', 'CRITICAL']);

    if (fraudPeriod === 'Yearly') {
      const years = Array.from({ length: 5 }, (_, idx) => dayjs().startOf('year').subtract(4 - idx, 'year'));
      return years.map((yearStart) => {
        const yearEnd = yearStart.endOf('year');
        const alertsInWindow = alertsRows.filter((alert) => {
          const ts = dayjs(alert.createdAt);
          return ts.isValid() && (ts.isAfter(yearStart) || ts.isSame(yearStart)) && (ts.isBefore(yearEnd) || ts.isSame(yearEnd));
        });
        return {
          month: yearStart.format('YYYY'),
          high: alertsInWindow.filter((alert) => highSeverity.has(alert.severity)).length,
          total: alertsInWindow.length,
        };
      });
    }

    const months = Array.from({ length: 6 }, (_, idx) => dayjs().startOf('month').subtract(5 - idx, 'month'));
    return months.map((monthStart) => {
      const monthEnd = monthStart.endOf('month');
      const alertsInWindow = alertsRows.filter((alert) => {
        const ts = dayjs(alert.createdAt);
        return ts.isValid() && (ts.isAfter(monthStart) || ts.isSame(monthStart)) && (ts.isBefore(monthEnd) || ts.isSame(monthEnd));
      });
      return {
        month: monthStart.format('MMM'),
        high: alertsInWindow.filter((alert) => highSeverity.has(alert.severity)).length,
        total: alertsInWindow.length,
      };
    });
  }, [alertsRows, fraudPeriod]);

  /* ── Top rules ────────────────────────────────────────────────────────── */
  const topRules = useMemo(() => {
    const counts = new Map<string, number>();
    rulesRows.forEach((rule) => counts.set(rule.ruleName, 0));
    alertsRows.forEach((alert) => {
      const ruleName = alert.ruleName || `Rule #${alert.ruleId}`;
      counts.set(ruleName, (counts.get(ruleName) ?? 0) + 1);
    });

    return Array.from(counts.entries())
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name))
      .slice(0, 5);
  }, [alertsRows, rulesRows]);
  const maxRule = Math.max(1, ...topRules.map((rule) => rule.count));

  /* ── Recent alerts list ───────────────────────────────────────────────── */
  const recentList = useMemo(
    () => [...alertsRows].sort((a, b) => dayjs(b.createdAt).valueOf() - dayjs(a.createdAt).valueOf()).slice(0, 5),
    [alertsRows],
  );

  /* ── Real-time activity feed ──────────────────────────────────────────── */
  const feed: FeedItem[] = useMemo(() => {
    const alertItems = alertsRows.slice(0, 5).map((alert) => ({
      iconBg: alert.severity === 'HIGH' || alert.severity === 'CRITICAL' ? 'bg-red-50' : 'bg-amber-50',
      icon: <AlertTriangle className={`h-3.5 w-3.5 ${alert.severity === 'HIGH' || alert.severity === 'CRITICAL' ? 'text-red-500' : 'text-amber-500'}`} />,
      text: `${alert.ruleName || 'Alert'} created`,
      ref: `ALERT-${alert.alertId}`,
      time: alert.createdAt,
    }));

    const transactionItems = transactionsRows.slice(0, 5).map((txn) => ({
      iconBg: 'bg-blue-50',
      icon: <Activity className="h-3.5 w-3.5 text-blue-500" />,
      text: `Transaction from ${txn.accountId} to ${txn.payeeName}`,
      ref: `TXN-${txn.transactionId}`,
      time: txn.timestamp || txn.createdAt,
    }));

    const ruleItems = rulesRows.slice(0, 5).map((rule) => ({
      iconBg: 'bg-emerald-50',
      icon: <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" />,
      text: `${rule.ruleName} (${rule.status.toLowerCase()})`,
      ref: `RULE-${rule.ruleId}`,
      time: rule.updatedAt,
    }));

    return [...alertItems, ...transactionItems, ...ruleItems]
      .sort((a, b) => dayjs(b.time).valueOf() - dayjs(a.time).valueOf())
      .slice(0, 5);
  }, [alertsRows, transactionsRows, rulesRows]);

  const systemStatuses = {
    database: queryStatus(txSummaryQuery.isSuccess && alertsQuery.isSuccess && rulesQuery.isSuccess, txSummaryQuery.isError || alertsQuery.isError || rulesQuery.isError),
    transactions: queryStatus(transactionsQuery.isSuccess, transactionsQuery.isError),
    rules: queryStatus(rulesQuery.isSuccess, rulesQuery.isError),
    alerts: queryStatus(alertsQuery.isSuccess && Boolean(alertStats), alertsQuery.isError),
  };

  /* ── Sparkline seeds ──────────────────────────────────────────────────── */
  const txSpark   = [3200,3800,3100,4200,4700,4100,4400];
  const altSpark  = [280,320,290,350,400,360,328];
  const hiSpark   = [55,62,58,70,80,72,67];
  const clsSpark  = [230,248,260,270,255,268,261];
  const ruleSpark = [20,22,21,23,24,22,24];
  const invSpark  = [35,38,40,44,48,45,42];

  /* ── Tooltip style ────────────────────────────────────────────────────── */
  const ttStyle = { fontSize: 11, borderRadius: 8, border: '1px solid #e5e7eb', padding: '6px 10px' };

  /* ── Period picker ────────────────────────────────────────────────────── */
  function PeriodPicker({ value, onChange, options }: { value: string; onChange: (v: string) => void; options: string[] }) {
    return (
      <select value={value} onChange={e => onChange(e.target.value)}
        className="rounded-lg border border-gray-200 bg-gray-50 px-2 py-1 text-xs font-medium text-gray-600 focus:outline-none dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300">
        {options.map(o => <option key={o}>{o}</option>)}
      </select>
    );
  }

  /* ── Legend row for donuts ────────────────────────────────────────────── */
  function LegendRow({ name, value, total, color }: { name: string; value: number; total: number; color: string }) {
    const pct = total > 0 ? ((value / total) * 100).toFixed(1) : '0';
    return (
      <div className="flex items-center justify-between gap-2 py-0.5 text-xs">
        <div className="flex items-center gap-1.5">
          <span className="h-2.5 w-2.5 flex-shrink-0 rounded-sm" style={{ backgroundColor: color }} />
          <span className="text-gray-600 dark:text-gray-400 capitalize">{name.charAt(0) + name.slice(1).toLowerCase()}</span>
        </div>
        <span className="font-semibold text-gray-800 dark:text-white">{value} <span className="font-normal text-gray-400">({pct}%)</span></span>
      </div>
    );
  }

  return (
    <div className="space-y-5">

      {/* ── Page Header ─────────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-black text-gray-900 dark:text-white">Dashboard</h1>
          <p className="text-xs text-gray-500 dark:text-gray-400">Welcome back, Admin! Here's what's happening in the system today.</p>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 rounded-xl border border-gray-200 bg-white px-3 py-2 text-xs text-gray-600 shadow-sm dark:border-gray-700 dark:bg-gray-900">
            <Calendar className="h-3.5 w-3.5 text-gray-400" />
            {dayjs(startDate).format('MMM D, YYYY')} - {dayjs(endDate).format('MMM D, YYYY')}
          </div>
          <input
            type="date"
            value={startDate}
            max={endDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="rounded-xl border border-gray-200 bg-white px-2 py-2 text-xs text-gray-600 shadow-sm outline-none focus:border-blue-500 dark:border-gray-700 dark:bg-gray-900 dark:text-gray-300"
          />
          <input
            type="date"
            value={endDate}
            min={startDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="rounded-xl border border-gray-200 bg-white px-2 py-2 text-xs text-gray-600 shadow-sm outline-none focus:border-blue-500 dark:border-gray-700 dark:bg-gray-900 dark:text-gray-300"
          />
        </div>
      </div>

      {/* ══ ROW 1 — KPI CARDS ══════════════════════════════════════════════ */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-3 xl:grid-cols-6">

        <KpiCard title="Total Transactions" value={totalTx.toLocaleString()} sub="All time"
          trend={15.8} trendUp icon={<Activity className="h-4 w-4" />}
          iconBg="bg-blue-50" iconClr="text-blue-600"
          spark={txSpark} sparkColor="#2563eb"
          onClick={() => navigate('/admin/metrics')} />

        <KpiCard title="Total Alerts" value={totalAlrts.toLocaleString()} sub="Generated"
          trend={22.4} trendUp icon={<AlertTriangle className="h-4 w-4" />}
          iconBg="bg-red-50" iconClr="text-red-600"
          spark={altSpark} sparkColor="#ef4444"
          onClick={() => navigate('/alerts')} />

        <KpiCard title="High Severity Alerts" value={totalHigh} sub="Needs action"
          trend={12.1} trendUp={false} icon={<Bell className="h-4 w-4" />}
          iconBg="bg-orange-50" iconClr="text-orange-500"
          spark={hiSpark} sparkColor="#f59e0b"
          onClick={() => navigate('/alerts?severity=HIGH')} />

        <KpiCard title="Closed Alerts" value={totalClosed} sub="Resolved"
          trend={10.1} trendUp icon={<CheckCircle2 className="h-4 w-4" />}
          iconBg="bg-emerald-50" iconClr="text-emerald-600"
          spark={clsSpark} sparkColor="#22c55e"
          onClick={() => navigate('/alerts/history')} />

        <KpiCard title="Active Rules" value={actRules}
          sub={`${actRules} Active • ${inactRulesC} Inactive`}
          icon={<ShieldCheck className="h-4 w-4" />}
          iconBg="bg-indigo-50" iconClr="text-indigo-600"
          spark={ruleSpark} sparkColor="#6366f1"
