          <div className="mt-2">
            <Sparkline data={[totalAmount, totalAmount, totalAmount, totalAmount, totalAmount]} color="#22c55e" />
          </div>
        </div>

        {/* Card 3 */}
        <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-900">
