          >
            <option value="">All</option>
            <option value="DEBIT">Debit</option>
            <option value="CREDIT">Credit</option>
          </select>
        </div>

        <div className="flex items-center gap-2 text-xs font-semibold text-gray-700 dark:text-gray-300">
